    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 38-year-old male named Edward presents with lightheadedness and chest tightness. Vitals are BP 82/56 mmHg, HR 44 bpm, RR 16 rpm, and SpO2 99%. The ECG shows a constant, normal PR interval but with intermittent dropped QRS complexes in a fixed ratio. What is the correct classification of this block, and what is the most appropriate immediate step?', '["Third-Degree AV Block; perform immediate synchronized cardioversion at 100 Joules", "First-Degree AV Block; administer oral aspirin and discharge home with outpatient cardiology referral", "Sinus arrhythmia; reassure the patient and advise avoiding caffeine and strenuous exercise", "Second-Degree AV Block Mobitz Type I (Wenckebach); administer intravenous atropine 1 mg and repeat the ECG in 30 minutes", "Second-Degree AV Block Mobitz Type II; immediately apply transcutaneous pacing pads and prepare for transvenous pacing due to high risk of progression to complete heart block"]'::jsonb, 4, 'This ECG description defines Second-Degree AV Block Mobitz Type II, characterized by a constant PR interval with intermittent dropped QRS complexes. This block occurs below the level of the AV node (in the Bundle of His or bundle branches) and carries a high risk of sudden progression to complete (third-degree) heart block and severe hemodynamic collapse. The immediate management for symptomatic Mobitz Type II block is the application of transcutaneous pacing pads and preparation for transvenous pacing. (Ref: Tintinalli''s Ch. 18; Step-Up to EM Ch. 2; Case Files: EM Case 2; Roberts & Hedges Ch. 15)'),
